    marker: marker,
    title: '[Bootcamp World] ' + world.task,
    body: body,
    payload: JSON.stringify({ title: '[Bootcamp World] ' + world.task, body: body }),
    search_query: 'repo:' + REPOSITORY + ' is:issue in:body "' + marker + '"'
